import { createHash } from "node:crypto";
import { normalizeServiceLocationName } from "./location_name_index";

/**
 * Versioned/additive District name-index contract.
 *
 * Do not substitute this into legacy callable writes until the Admin Dart
 * implementation uses the same ordered parent tuple. Existing legacy index
 * IDs remain generated by serviceLocationNameIndexId().
 */
export const DISTRICT_NAME_INDEX_COLLECTIONS = {
  district: "service_districts",
  city: "service_cities",
  area: "service_areas",
  locality: "service_localities",
} as const;

export type DistrictIndexedType = keyof typeof DISTRICT_NAME_INDEX_COLLECTIONS;

const SAFE_ID = /^[A-Za-z0-9_-]{1,128}$/;

function normalizeIds(ids: readonly string[]): string[] {
  return ids.map((id) => {
    if (typeof id !== "string" || id !== id.trim() || !SAFE_ID.test(id)) {
      throw new Error("DISTRICT_INDEX_PARENT_INVALID");
    }
    return id;
  });
}

/**
 * Returns the ordered parent tuple for the district-aware schema.
 * The caller must derive IDs from trusted Firestore documents, not trust
 * client-provided ancestry as proof of parent relationships.
 */
export function districtAwareParentIds(
  type: DistrictIndexedType,
  parents: {
    countryId?: string;
    stateId?: string;
    districtId?: string;
    cityId?: string;
    areaId?: string;
  },
): string[] {
  const required: Record<DistrictIndexedType, readonly (keyof typeof parents)[]> = {
    district: ["countryId", "stateId"],
    city: ["countryId", "stateId", "districtId"],
    area: ["countryId", "stateId", "districtId", "cityId"],
    locality: ["countryId", "stateId", "districtId", "cityId", "areaId"],
  };
  const fields = required[type];
  const raw: string[] = [];
  for (const field of fields) {
    const value = parents[field];
    if (typeof value !== "string") throw new Error("DISTRICT_INDEX_PARENT_INVALID");
    raw.push(value);
  }
  return normalizeIds(raw);
}

/**
 * Calculate the proposed district-aware index ID. Collection path and tuple
 * ordering intentionally mirror the existing SHA-256 JSON tuple convention.
 */
export function districtAwareNameIndexId(
  type: DistrictIndexedType,
  parents: {
    countryId?: string;
    stateId?: string;
    districtId?: string;
    cityId?: string;
    areaId?: string;
  },
  name: string,
): string {
  const normalizedName = normalizeServiceLocationName(name);
  if (!normalizedName || normalizedName.length > 120) {
    throw new Error("DISTRICT_INDEX_NAME_INVALID");
  }
  const collection = DISTRICT_NAME_INDEX_COLLECTIONS[type];
  const parentIds = districtAwareParentIds(type, parents);
  const tuple = JSON.stringify([collection, parentIds, normalizedName]);
  return createHash("sha256").update(Buffer.from(tuple, "utf8")).digest("hex");
}
